code:
.message {
  display: flex;
  align-items: start;
  gap: 12px;
  padding: 16px 0;
  min-width: 0;
}
.avatar {
  display: grid;
  place-items: center;
  flex: 0 0 24px;
  height: 24px;
  border-radius: 6px;
  border: 1px solid var(--border);
}
.avatar svg {
  stroke-width: 1.75;
}
.main {
  flex: 1;
  min-width: 0;
}
.main header {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  min-height: 20px;
  font-size: 12px;
  line-height: 16px;
  font-weight: 500;
}
.main time {
  color: var(--text-secondary);
  font-family: monospace;
  font-weight: 400;
}
.actions {
  display: flex;
  gap: 4px;
  margin-left: auto;
  opacity: 0;
}
.message:hover .actions,
.message:focus-within .actions {
  opacity: 1;
}
.body {
  margin-top: 8px;
  font-size: 14px;
  line-height: 24px;
  overflow-wrap: anywhere;
}
.body p {
  white-space: pre-wrap;
  margin-bottom: 12px;
}
.body p:last-child {
  margin-bottom: 0;
}
.body h3 {
  font-size: 16px;
  line-height: 24px;
  font-weight: 500;
  margin-block: 12px;
}
.body ul,
.body ol {
  padding-left: 20px;
}
.body pre {
  overflow: auto;
  max-height: 320px;
  padding: 12px;
  font: 12px/20px monospace;
  border: 1px solid var(--border);
  border-radius: 6px;
  white-space: pre;
}
.attachments {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 8px;
  min-height: 32px;
  font-size: 12px;
}
.state {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
  font-size: 12px;
  line-height: 20px;
  color: var(--text-secondary);
}
.state[data-error="true"] {
  color: var(--destructive);
}
.state p {
  flex-basis: 100%;
}
.feedback {
  font-size: 12px;
  line-height: 20px;
  color: var(--text-secondary);
  margin-top: 4px;
}
.feedback:empty {
  display: none;
}
.conversation {
  container: conversation / inline-size;
  min-width: 0;
}
.conversation[data-layout="fill"] {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
}
.conversation[data-layout="fill"] > .panes {
  flex: 1;
  min-height: 0;
}
.conversation[data-layout="fill"] .panes .chatPane {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-height: 0;
}
.conversation[data-layout="fill"] .panes[data-view="workspace"] .chatPane {
  display: none;
}
.conversation[data-layout="fill"] .workspace {
  min-height: 0;
  max-height: none;
}
.conversation[data-layout="fill"] .scroll {
  flex: 1;
  min-height: 0;
  max-height: none;
}
.conversation[data-layout="fill"] .latest {
  flex-shrink: 0;
}
.panes {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  min-width: 0;
}
.chatPane {
  min-width: 0;
}
.scroll {
  overflow-anchor: none;
  max-height: 440px;
  overflow: auto;
  overscroll-behavior: contain;
}
.scroll:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: -2px;
}
.messages {
  max-width: 800px;
  margin-inline: auto;
}
.messages > div {
  margin-bottom: 24px;
}
.messages > div:last-child {
  margin-bottom: 0;
}
.after {
  margin: 0 0 0 36px;
  min-width: 0;
}
.workspace {
  min-width: 0;
  padding: 16px;
  border-left: 1px solid var(--border);
  overflow: auto;
  max-height: 440px;
}
.latest {
  margin-block: 8px;
}
.tabs {
  display: flex;
  gap: 4px;
  border-bottom: 1px solid var(--border);
  margin-bottom: 8px;
}
.tabs button {
  min-height: 32px;
  padding: 4px 12px;
  border: 0;
  border-bottom: 2px solid transparent;
  background: transparent;
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 20px;
  cursor: pointer;
}
.tabs button[aria-selected="true"] {
  border-bottom-color: var(--primary);
  color: var(--foreground);
}
.tabs button:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: -2px;
}
.panes[data-view="conversation"] .workspace {
  display: none;
}
.panes[data-view="workspace"] .chatPane {
  display: none;
}
.composer {
  padding: 12px;
  border-top: 1px solid var(--border);
}
.composer textarea {
  display: block;
  width: 100%;
  min-height: 80px;
  max-height: 200px;
  padding: 12px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--surface);
  color: inherit;
  font-size: 14px;
  line-height: 24px;
  resize: vertical;
}
.composer textarea:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}
.composer textarea[aria-invalid="true"] {
  border-color: var(--destructive);
}
.composerActions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 8px;
}
.composerActions > span {
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 16px;
}
.composerError {
  font-size: 12px;
  line-height: 20px;
  color: var(--destructive);
  margin-top: 8px;
}
@container conversation (min-width: 800px) {
  .conversation[data-layout="fill"] .panes[data-view] .chatPane {
    display: flex;
  }
  .tabs {
    display: none;
  }
  .panes[data-split="true"] {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    gap: 16px;
  }
  .panes[data-view] .workspace,
  .panes[data-view] .chatPane {
    display: block;
  }
}
@media (pointer: coarse) {
  .actions {
    opacity: 1;
  }
  .tabs button {
    min-height: 44px;
  }
}

/* Opt-in browser deferral retains all text for search/copy and accessibility. */
.messages[data-defer-offscreen] > .messageEntry {
  content-visibility: auto;
  contain-intrinsic-block-size: auto 88px;
}
